const sessionId = typeof $json.sessionId === 'string' ? $json.sessionId.trim() : '';
const requestId = typeof $json.requestId === 'string' ? $json.requestId.trim() : '';
const rawDomain = typeof $json.domain === 'string' ? $json.domain.trim() : '';
const companyName = typeof $json.companyName === 'string' ? $json.companyName.trim() : '';
const researchDepth = typeof $json.researchDepth === 'string' && $json.researchDepth.trim() ? $json.researchDepth.trim().toLowerCase() : 'standard';
const authorizationConfirmed = $json.authorizationConfirmed === true;
const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
let domain = '';
let error = null;
try {
  const parsed = new URL(rawDomain.includes('://') ? rawDomain : `https://${rawDomain}`);
  const hostname = parsed.hostname.toLowerCase().replace(/\.$/, '').replace(/^www\./, '');
  const labels = hostname.split('.');
  if (!['http:', 'https:'].includes(parsed.protocol) || parsed.username || parsed.password || (parsed.port && !['80', '443'].includes(parsed.port)) || labels.length < 2 || labels.some((label) => !/^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/.test(label)) || /^(?:\d{1,3}\.){3}\d{1,3}$/.test(hostname) || ['local', 'internal', 'localhost', 'home', 'lan'].includes(labels.at(-1))) {
    throw new Error('not public');
  }
  domain = hostname;
} catch {
  error = { code: 'INVALID_DOMAIN', message: 'Use a complete public business domain such as example.com.' };
}
if (!error && (!uuidPattern.test(sessionId) || !uuidPattern.test(requestId))) {
  error = { code: 'INVALID_SESSION', message: 'The research request needs a valid conversation and request ID.' };
} else if (!error && !authorizationConfirmed) {
  error = { code: 'AUTHORIZATION_REQUIRED', message: 'Confirm that you own or are authorised to research this public domain first.' };
} else if (!error && !['standard', 'deep'].includes(researchDepth)) {
  error = { code: 'INVALID_RESEARCH_DEPTH', message: 'Research depth must be standard or deep.' };
} else if (!error && companyName.length > 200) {
  error = { code: 'INVALID_COMPANY_NAME', message: 'Company name must be 200 characters or fewer.' };
}
const proposedInput = { sessionId, requestId, domain, companyName, researchDepth, authorizationConfirmed };
return { json: { valid: error === null, ...proposedInput, proposedInput, ...(error ? { response: { ok: false, error } } : {}) } };

const input = $('Validate Start Input').first().json;
const jobId = typeof $json.jobId === 'string' ? $json.jobId : '';
const accepted = jobId !== '' && ['queued', 'running'].includes(String($json.status ?? ''));
const response = accepted
  ? { ok: true, status: String($json.status), jobId, domain: input.domain, statusUrl: String($json.statusUrl ?? ''), message: 'Domain research started. Check this job again shortly; completed results will be saved to local business memory.' }
  : { ok: false, error: { code: 'RESEARCH_START_FAILED', message: String($json.message ?? $json.error?.message ?? 'Content Factory could not start domain research.') } };
return { json: { ...input, shouldRegister: accepted, response } };

const prepared = $('Prepare Job Registration').first().json;
const registered = typeof $json.job?.jobId === 'string' && $json.job.jobId === prepared.response.jobId;
return { json: { ...prepared, response: registered ? prepared.response : { ok: false, error: { code: 'JOB_REGISTRATION_FAILED', message: 'Research started, but its job ID could not be safely linked to this conversation. Try starting it again.' } } } };

const input = $('Validate Start Input').first().json;
const response = $json.response ?? { ok: false, error: { code: 'RESEARCH_START_FAILED', message: 'Domain research could not be started.' } };
return { json: { occurredAt: new Date().toISOString(), sessionId: input.sessionId, requestId: input.requestId, toolName: 'start_domain_research', proposedInput: JSON.stringify(input.proposedInput ?? {}), result: JSON.stringify(response), error: response.ok === false ? String(response.error?.message ?? 'Tool failed') : '', response } };

const prepared = $('Prepare Audit').item.json;
const response = { ...prepared.response };
if (!Number.isInteger($json.id)) response.auditWarning = 'The tool result could not be written to the local audit table.';
return { json: response };
